<?php
require_once dirname(__DIR__,3).'/neptune_secure/bootstrap.php';
$u=require_login();$org=(int)$u['organization_id'];
$q="SELECT a.*,e.name event_name,m.comp_level,m.set_number,m.match_number FROM scouting_actions a JOIN events e ON e.id=a.event_id JOIN matches m ON m.id=a.match_id WHERE a.deleted_at IS NULL AND (a.organization_id=? OR a.owner_team_id IN (SELECT sr.owner_team_id FROM sharing_relationships sr JOIN teams rt ON rt.id=sr.recipient_team_id WHERE rt.organization_id=? AND sr.status='active' AND sr.share_raw_actions=1 AND (sr.starts_at IS NULL OR sr.starts_at<=UTC_TIMESTAMP()) AND (sr.expires_at IS NULL OR sr.expires_at>=UTC_TIMESTAMP()))) ORDER BY a.id DESC LIMIT 500";
$s=$pdo->prepare($q);$s->execute([$org,$org]);$rows=$s->fetchAll();$pageTitle='Scouting Data';include dirname(__DIR__).'/partials_header.php';
?><div class="toolbar" style="justify-content:space-between"><div><h1 style="margin-bottom:4px">Raw Scouting Data</h1><div class="muted">Most recent 500 actions, including permitted shared raw data.</div></div><a class="btn secondary" href="<?=e(base_url('analytics/index.php'))?>"><i class="fa-solid fa-chart-column"></i> Analytics</a></div><div class="card"><div class="table-wrap"><table class="table"><tr><th>Event</th><th>Match</th><th>Run</th><th>Robot</th><th>Time</th><th>Action</th><th>Result</th><th>Pts</th><th>Source</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['event_name'])?></td><td><?=e(neptune_match_label($r))?></td><td><?=e($r['match_run_number']??1)?></td><td>#<?=e($r['frc_team_number'])?></td><td><?=e($r['match_time_sec'])?></td><td><?=e($r['action_name']?:$r['action_code'])?></td><td><?=e($r['result'])?></td><td><?=e($r['points'])?></td><td><?=e($r['source'])?></td></tr><?php endforeach;?></table></div></div><?php include dirname(__DIR__).'/partials_footer.php';
